//! `winemetal.dll`'s `SM50*` exports: the shader translator's entry points, as thunks.
//!
//! The translator runs in `winemetal.so`. Each export fills its call's params structure of
//! `airconv_thunks.h` (zeroed, then each field the caller gave), makes the Unix call of its slot
//! and hands back what the handler wrote. `SM50Initialize` and the compile calls answer -1 when
//! the Unix call itself fails; the others have nothing to answer it with. Windows only: natively
//! `winemetal.dylib` holds the translator itself, whose exports have these names. `abi.rs`,
//! generated by `tools/winemetal-layouts.sh --seam-abi src/winemetal/sys/sm50-abi.h crate::sm50`,
//! asserts each export's signature against clang's AST on the four Windows targets.

use core::ffi::{c_char, c_void};

use winemetal_wire::{
    Sm50CompileGeometryPipelineGeometryParams, Sm50CompileGeometryPipelineVertexParams,
    Sm50CompileParams, Sm50CompileTessellationPipelineDomainParams,
    Sm50CompileTessellationPipelineHullParams, Sm50DestroyBitcodeParams, Sm50DestroyParams,
    Sm50FreeErrorParams, Sm50GetArgumentsInfoParams, Sm50GetCompiledBitcodeParams,
    Sm50GetErrorMessageParams, Sm50InitializeParams, slot,
};

use crate::transport::{call, call_status};

#[cfg(windows)]
mod abi;
#[cfg(test)]
mod tests;

/// `struct MTL_SHADER_REFLECTION`, which the Unix side writes and no thunk reads.
#[repr(C)]
pub struct MtlShaderReflection {
    _opaque: [u8; 0],
}

/// `struct SM50_SHADER_COMPILATION_ARGUMENT_DATA`, the head of a chain the Unix side walks.
#[repr(C)]
pub struct Sm50ShaderCompilationArgumentData {
    _opaque: [u8; 0],
}

/// `struct SM50_COMPILED_BITCODE`, which the Unix side writes and no thunk reads.
#[repr(C)]
pub struct Sm50CompiledBitcode {
    _opaque: [u8; 0],
}

/// `struct MTL_SM50_SHADER_ARGUMENT`, an array the Unix side writes and no thunk reads.
#[repr(C)]
pub struct MtlSm50ShaderArgument {
    _opaque: [u8; 0],
}

/// What `SM50Initialize` and a compile call answer.
///
/// The handler's `ret`, or -1 when the Unix call itself failed.
const fn answer(ret: i32, status: i32) -> i32 {
    if status == 0 { ret } else { -1 }
}

exports! {
    fn SM50Initialize(
        bytecode: *const c_void,
        bytecode_size: usize,
        shader: *mut u64,
        reflection: *mut MtlShaderReflection,
        error: *mut u64,
    ) -> i32 {
        let (p, status) = call_status(slot::SM50_INITIALIZE, |p: &mut Sm50InitializeParams| {
            p.bytecode = bytecode;
            p.bytecode_size = bytecode_size;
            p.shader = shader;
            p.reflection = reflection.cast();
            p.error = error;
        });
        answer(p.ret, status)
    }

    fn SM50Destroy(shader: u64) {
        call(slot::SM50_DESTROY, |p: &mut Sm50DestroyParams| p.shader = shader);
    }

    fn SM50Compile(
        shader: u64,
        args: *mut Sm50ShaderCompilationArgumentData,
        func_name: *const c_char,
        bitcode: *mut u64,
        error: *mut u64,
    ) -> i32 {
        let (p, status) = call_status(slot::SM50_COMPILE, |p: &mut Sm50CompileParams| {
            p.shader = shader;
            p.args = args.cast();
            p.func_name = func_name;
            p.bitcode = bitcode;
            p.error = error;
        });
        answer(p.ret, status)
    }

    fn SM50GetCompiledBitcode(bitcode: u64, data: *mut Sm50CompiledBitcode) {
        call(slot::SM50_GET_COMPILED_BITCODE, |p: &mut Sm50GetCompiledBitcodeParams| {
            p.bitcode = bitcode;
            p.data_out = data.cast();
        });
    }

    fn SM50DestroyBitcode(bitcode: u64) {
        call(slot::SM50_DESTROY_BITCODE, |p: &mut Sm50DestroyBitcodeParams| p.bitcode = bitcode);
    }

    fn SM50GetErrorMessage(error: u64, buffer: *mut c_char, buffer_size: usize) -> usize {
        call(slot::SM50_GET_ERROR_MESSAGE, |p: &mut Sm50GetErrorMessageParams| {
            p.error = error;
            p.buffer = buffer;
            p.buffer_size = buffer_size;
        })
        .ret_size
    }

    fn SM50FreeError(error: u64) {
        call(slot::SM50_FREE_ERROR, |p: &mut Sm50FreeErrorParams| p.error = error);
    }

    fn SM50CompileTessellationPipelineHull(
        vertex: u64,
        hull: u64,
        hull_args: *mut Sm50ShaderCompilationArgumentData,
        func_name: *const c_char,
        bitcode: *mut u64,
        error: *mut u64,
    ) -> i32 {
        let (p, status) = call_status(
            slot::SM50_COMPILE_TESSELLATION_HULL,
            |p: &mut Sm50CompileTessellationPipelineHullParams| {
                p.vertex = vertex;
                p.hull = hull;
                p.hull_args = hull_args.cast();
                p.func_name = func_name;
                p.bitcode = bitcode;
                p.error = error;
            },
        );
        answer(p.ret, status)
    }

    fn SM50CompileTessellationPipelineDomain(
        hull: u64,
        domain: u64,
        domain_args: *mut Sm50ShaderCompilationArgumentData,
        func_name: *const c_char,
        bitcode: *mut u64,
        error: *mut u64,
    ) -> i32 {
        let (p, status) = call_status(
            slot::SM50_COMPILE_TESSELLATION_DOMAIN,
            |p: &mut Sm50CompileTessellationPipelineDomainParams| {
                p.hull = hull;
                p.domain = domain;
                p.domain_args = domain_args.cast();
                p.func_name = func_name;
                p.bitcode = bitcode;
                p.error = error;
            },
        );
        answer(p.ret, status)
    }

    fn SM50CompileGeometryPipelineVertex(
        vertex: u64,
        geometry: u64,
        vertex_args: *mut Sm50ShaderCompilationArgumentData,
        func_name: *const c_char,
        bitcode: *mut u64,
        error: *mut u64,
    ) -> i32 {
        let (p, status) = call_status(
            slot::SM50_COMPILE_GEOMETRY_PIPELINE_VERTEX,
            |p: &mut Sm50CompileGeometryPipelineVertexParams| {
                p.vertex = vertex;
                p.geometry = geometry;
                p.vertex_args = vertex_args.cast();
                p.func_name = func_name;
                p.bitcode = bitcode;
                p.error = error;
            },
        );
        answer(p.ret, status)
    }

    fn SM50CompileGeometryPipelineGeometry(
        vertex: u64,
        geometry: u64,
        geometry_args: *mut Sm50ShaderCompilationArgumentData,
        func_name: *const c_char,
        bitcode: *mut u64,
        error: *mut u64,
    ) -> i32 {
        let (p, status) = call_status(
            slot::SM50_COMPILE_GEOMETRY_PIPELINE_GEOMETRY,
            |p: &mut Sm50CompileGeometryPipelineGeometryParams| {
                p.vertex = vertex;
                p.geometry = geometry;
                p.geometry_args = geometry_args.cast();
                p.func_name = func_name;
                p.bitcode = bitcode;
                p.error = error;
            },
        );
        answer(p.ret, status)
    }

    fn SM50GetArgumentsInfo(
        shader: u64,
        constant_buffers: *mut MtlSm50ShaderArgument,
        arguments: *mut MtlSm50ShaderArgument,
    ) {
        call(slot::SM50_GET_ARGUMENTS_INFO, |p: &mut Sm50GetArgumentsInfoParams| {
            p.shader = shader;
            p.constant_buffers = constant_buffers.cast();
            p.arguments = arguments.cast();
        });
    }
}
